class DivideByZeroException extends Exception { DivideByZeroException() { super("Cannot divide by zero"); } } class OutOfStockException extends Exception { OutOfStockException(int shortfall) { super("Out of stock by " + shortfall); } } class InvalidQuantityException extends Exception { InvalidQuantityException() { super("Quantity must be positive"); } } class Warehouse { private int stock=5; void issue(int quantity) throws OutOfStockException, InvalidQuantityException { if(quantity<=0) throw new InvalidQuantityException(); if(quantity>stock) throw new OutOfStockException(quantity-stock); stock-=quantity; } } class AuditResource implements AutoCloseable { public void close() { System.out.println("resource closed"); } }
public class Practical8Demo { static double divide(double a,double b) throws DivideByZeroException { if(b==0) throw new DivideByZeroException(); return a/b; } public static void main(String[] args) { try (AuditResource ignored=new AuditResource()) { System.out.println(divide(10,2)); new Warehouse().issue(9); } catch(Exception e) { System.out.println(e.getMessage()); } finally { System.out.println("Attempt logged"); } } }
